// And groups predicates with the AND operator between them.
func And(predicates ...predicate.GroupBuyEntitlement) predicate.GroupBuyEntitlement {
	return predicate.GroupBuyEntitlement(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
